/bin/zsh -lc "node --experimental-strip-types --input-type=module -e '
import assert from \"node:assert/strict\";
import { CITIES, DEFAULT_CITY_IDS, formatShortLocalTime, getContiguousRanges, getInstantForZonedHour, getOffsetMinutes, isAwakeAt } from \"./src/timezones.ts\";
const instant = new Date(\"2026-09-23T12:00:00Z\");
assert.equal(CITIES.length, 36);
assert.equal(DEFAULT_CITY_IDS.join(\",\"), \"san-francisco,denpasar,geneva\");
for (const city of CITIES) new Intl.DateTimeFormat(\"en-US\", { timeZone: city.timezone }).format(instant);
assert.equal(getOffsetMinutes(instant, \"Asia/Kolkata\"), 330);
assert.equal(getOffsetMinutes(instant, \"Asia/Kathmandu\"), 345);
const referenceDate = { year: 2026, month: 9, day: 23 };
const sfNine = getInstantForZonedHour(referenceDate, \"America/Los_Angeles\", 9);
assert.equal(formatShortLocalTime(sfNine, \"America/Los_Angeles\", \"12h\"), \"9a\");
assert.equal(formatShortLocalTime(sfNine, \"Asia/Kathmandu\", \"12h\"), \"9:45p\");
const sfTwentyTwo = getInstantForZonedHour(referenceDate, \"America/Los_Angeles\", 22);
const sfTwentyThree = getInstantForZonedHour(referenceDate, \"America/Los_Angeles\", 23);
assert.equal(isAwakeAt(sfTwentyTwo, \"America/Los_Angeles\", 7, 23), true);
assert.equal(isAwakeAt(sfTwentyThree, \"America/Los_Angeles\", 7, 23), false);
assert.equal(isAwakeAt(sfNine, \"America/Los_Angeles\", 22, 6), false);
assert.equal(isAwakeAt(getInstantForZonedHour(referenceDate, \"America/Los_Angeles\", 2), \"America/Los_Angeles\", 22, 6), true);
assert.deepEqual(getContiguousRanges([1, 2, 3, 8]), [{ start: 1, end: 4 }, { start: 8, end: 9 }]);
console.log(\"Timezone checks passed: catalog, fractional offsets, reference-hour conversion, awake windows, and ranges.\");
'"

