import assert from \"node:assert/strict\";
import { CITIES, DEFAULT_CITY_IDS, formatRangeHour, getContiguousRanges, getInstantForZonedHour, getZonedDate, isAwakeAt } from \"./src/timezones.ts\";
const now = new Date(\"2026-09-23T12:00:00Z\");
const defaults = DEFAULT_CITY_IDS.map((id) => CITIES.find((city) => city.id === id));
const day = getZonedDate(now, defaults[0].timezone);
const sharedHours = Array.from({ length: 24 }, (_, hour) => {
  const instant = getInstantForZonedHour(day, defaults[0].timezone, hour);
  return defaults.every((city) => isAwakeAt(instant, city.timezone, 7, 23)) ? hour : null;
}).filter((hour) => hour "'!== null);
assert.deepEqual(sharedHours, [7, 22]);
assert.deepEqual(getContiguousRanges(sharedHours), [{ start: 7, end: 8 }, { start: 22, end: 23 }]);
assert.equal(formatRangeHour(7, "12h"), "7am");
assert.equal(formatRangeHour(23, "12h"), "11pm");
console.log("Default summary check passed: 2 shared hours (7–8am and 10–11pm San Francisco time).");
'"'"

